 function navigateStep(delta,{source='user'}={}){if(transition<1||!ready||loadingScene)return false;const shot=shots[index],b=forestBeat(narrative.frame(shot,time));

  if(delta>0&&b.actionPending)return false;
  if(delta>0&&b.protectedStart){const source=castSnapshot();const ok=beatChange(1);entryState={pose:source,progress:0,prologue:true};return ok;}
  if(delta>0&&(rendered?.actors.some(a=>a.native?.airborne>0)||(isVineyard()||b.close==='action')&&rendered?.actionReady===false))return false;

  if(shot.mode==='ceremony'&&delta>0&&(b.index===0||b.view==='macro')&&!rendered?.ceremony?.nextReady)return false;

  if(isForest()&&b.choiceResult){
   cancelForestInput();
   if(delta<0){if(forestAction.retreat()){forestChanged({historyStep:true});return true;}}
   else if(forestAction.snapshot().phase==='cross'&&!forestAction.canContinue())return false;else if(forestAction.snapshot().phase!=='rest'){forestAction.advance({force:true});forestChanged({historyStep:true});return true;}
  }
  if(source==='cinema'&&b.kind==='choice')return false;
  if(delta>0&&b.kind==='choice'&&!choices.option(b.choiceId)){choices.skip(b.choiceId);if(isForest()){VF.Journey.invalidateRoute(session);forestAction.select('neutral',{replay:true});}}
  if(delta>0&&b.choiceResult&&b.choiceDefinition?.rejoinNode){const to=narrative.beats(shot).find(n=>n.id===b.choiceDefinition.rejoinNode);if(to?.departure){narrative.record(shot).complete=true;return go(index+1);}return jumpStoryBeat(b.choiceDefinition.rejoinNode);}
  if(reader.active){if(reader.step(delta)){sound.cue('paper');if(paused||reduced.matches)reader.hold();ui();draw();save();history.pushState(routeState(),'',location.hash);return true;}if(delta>0){session.letter.complete=true;session.flush();}return beatChange(delta);}

  if(beatChange(delta))return true;

  if(delta>0&&(rendered?.actors.some(a=>a.native?.airborne>0)||(isVineyard()||b.close==='action')&&rendered?.actionReady===false))return false;

  if(shot.mode==='ceremony'&&delta>0){session.ceremony.complete=true;session.flush();}

  if(index+delta<0||index+delta>=shots.length)return false;return go(index+delta);

 }

